import os, resource, signal, subprocess, sys, random, math
D = '/tmp/eval_gemm'
SRC = 'gemm.go'
EXE = 'gemm'
BUILD = ['go', 'build', '-o', 'gemm', 'gemm.go']
RUN = [sys.executable, SRC] if BUILD is None else ['./' + EXE]


def fail(msg):
    print('FAIL: ' + msg)
    sys.exit(1)


if not os.path.isfile(os.path.join(D, SRC)):
    fail(SRC + ' not found in ' + D)
os.chdir(D)
_build = None


def start_build():
    global _build
    if BUILD is None:
        return
    if os.path.exists(EXE):
        os.remove(EXE)
    _build = subprocess.Popen(BUILD, stdout=subprocess.PIPE, stderr=subprocess.STDOUT)


def finish_build():
    if _build is None:
        return
    try:
        out, _ = _build.communicate(timeout=25)
    except subprocess.TimeoutExpired:
        _build.kill()
        fail('compile timed out')
    if _build.returncode != 0 or not os.path.isfile(EXE):
        fail('compile failed: ' + out.decode('utf-8', 'replace')[-400:])


def _child_cpu():
    r = resource.getrusage(resource.RUSAGE_CHILDREN)
    return r.ru_utime + r.ru_stime


# The limit is CPU seconds (user + system, every thread), with a looser wall
# backstop for a solution that sleeps or blocks: wall time on a loaded host
# (and macOS's first-exec check of a fresh binary) says nothing about the code.
def launch(inp, cpu, wall):
    def cap():
        resource.setrlimit(resource.RLIMIT_CPU, (cpu, cpu + 1))
    t0 = _child_cpu()
    p = subprocess.Popen(RUN, stdin=subprocess.PIPE, stdout=subprocess.PIPE,
                         stderr=subprocess.DEVNULL, preexec_fn=cap)
    data = inp.encode()
    if len(data) <= 4096:
        p.stdin.write(data)
        p.stdin.close()
        p.stdin = None
        data = None
    return p, t0, data, cpu, wall


def finish(job):
    p, t0, data, cpu, wall = job
    try:
        out, _ = p.communicate(data, timeout=wall)
    except subprocess.TimeoutExpired:
        p.kill()
        p.communicate()
        fail('solution timed out (wall limit %gs)' % wall)
    if p.returncode == -signal.SIGXCPU or _child_cpu() - t0 > cpu:
        fail('solution timed out (CPU limit %gs)' % cpu)
    if p.returncode != 0:
        fail('solution exited with status %d' % p.returncode)
    return out.decode('utf-8', 'replace')


def run(inp, cpu, wall):
    return finish(launch(inp, cpu, wall))


def numbers(text, want, case):
    toks = text.split()
    if len(toks) != want:
        fail('case %d: expected %d output values, got %d' % (case, want, len(toks)))
    try:
        return [float(t) for t in toks]
    except ValueError:
        fail('case %d: unparseable output value' % case)

from operator import mul
GP = 2147483647
GG = 48271


def gm_seq(seed, start, count):
    x = seed * pow(GG, start, GP) % GP
    out = [0] * count
    for t in range(count):
        x = x * GG % GP
        out[t] = x
    return out


_gm_cols = {}


def gm_rows(n, seed, rows):
    cols = _gm_cols.get((n, seed))
    if cols is None:
        b = [v / GP for v in gm_seq(seed, n * n, n * n)]
        cols = _gm_cols[(n, seed)] = [b[j::n] for j in range(n)]
    res = {}
    for i in rows:
        a = [v / GP for v in gm_seq(seed, i * n, n)]
        c = [sum(map(mul, a, col)) for col in cols]
        res[i] = (sum(v * v for v in c), max(c))
    return res

CPU, WALL = 12, 20
rng = random.Random(0x6E33)
seed = lambda: rng.randrange(1, GP)
small = [(1, seed()), (2, seed()), (17, seed()), (100, seed()), (257, seed())]
big_n = 2048
big = (big_n, seed())
big_rows = sorted({0, big_n - 1} | set(rng.sample(range(1, big_n - 1), 10)))
# Six more rows of the big case are drawn fresh on every run: the seeded rows
# fix what a wrong solution is judged on, and the unseeded ones mean that no
# reading of this script tells a solution which rows it may skip.
spare = [i for i in range(big_n) if i not in big_rows]
extra_rows = random.SystemRandom().sample(spare, 6)
start_build()
want = [gm_rows(n, s, range(n)) for n, s in small]
want_big = gm_rows(big[0], big[1], big_rows)
finish_build()


def check(case, n, got_text, rows):
    got = numbers(got_text, 2 * n, case)
    for i, (S, M) in rows.items():
        for g, w in ((got[2 * i], S), (got[2 * i + 1], M)):
            if not abs(g - w) <= 1e-9 * abs(w) + 1e-12:
                fail('mismatch at case %d' % case)


for c, ((n, s), w) in enumerate(zip(small, want)):
    check(c, n, run('%d %d\n' % (n, s), CPU, WALL), w)
job = launch('%d %d\n' % big, CPU, WALL)
want_big.update(gm_rows(big[0], big[1], extra_rows))
check(len(small), big[0], finish(job), want_big)
print('OK: %d hidden cases' % (len(small) + 1))

